begin;
do $$ declare t text; begin foreach t in array array['member_permission_overrides','chronology_events','deadline_rules','matter_deadlines','organization_billing_profiles','organization_subscriptions','billing_attempts','usage_counters'] loop execute format('create trigger %I_updated before update on %I for each row execute function set_updated_at()',t,t); end loop; end $$;
create policy conflict_alias_write on conflict_subject_aliases for insert with check(exists(select 1 from conflict_check_subjects s join conflict_checks c on c.id=s.conflict_check_id where s.id=conflict_check_subject_id and c.requested_by=current_app_user_id() and has_app_permission(c.organization_id,'run_conflict_check')));
create policy conflict_match_write on conflict_matches for insert with check(exists(select 1 from conflict_checks c where c.id=conflict_check_id and c.requested_by=current_app_user_id() and has_app_permission(c.organization_id,'run_conflict_check')));
create policy conflict_check_update on conflict_checks for update using(requested_by=current_app_user_id() and has_app_permission(organization_id,'run_conflict_check')) with check(requested_by=current_app_user_id() and has_app_permission(organization_id,'run_conflict_check'));
create policy brief_source_access on hearing_brief_sources for select using(exists(select 1 from hearing_briefs b join hearings h on h.id=b.hearing_id where b.id=hearing_brief_id and can_access_matter(h.matter_id,'view')));
create policy brief_source_write on hearing_brief_sources for all using(exists(select 1 from hearing_briefs b join hearings h on h.id=b.hearing_id where b.id=hearing_brief_id and can_access_matter(h.matter_id,'edit'))) with check(exists(select 1 from hearing_briefs b join hearings h on h.id=b.hearing_id where b.id=hearing_brief_id and can_access_matter(h.matter_id,'edit')));
create policy subscription_write on organization_subscriptions for insert with check(has_app_permission(organization_id,'manage_subscription'));
create policy subscription_change on organization_subscriptions for update using(has_app_permission(organization_id,'manage_subscription')) with check(has_app_permission(organization_id,'manage_subscription'));
create policy billing_attempt_write on billing_attempts for insert with check(has_app_permission(organization_id,'manage_subscription') and initiated_by=current_app_user_id());
create policy billing_attempt_change on billing_attempts for update using(has_app_permission(organization_id,'manage_subscription')) with check(has_app_permission(organization_id,'manage_subscription'));
commit;
